(()=>{'use strict';const M=window.SquatModel,T=window.SQUAT_COPY,$=id=>document.getElementById(id),keys=Object.keys(M.defaults),colors={hip:'#47ff9e',knee:'#ff47a8',ankle:'#5c9dff'};let p=M.parameters(),mode='dynamic',running=false,frame=null,last=null,trace=[];
const storage='bodytrack-squat-v1';try{const v=JSON.parse(sessionStorage.getItem(storage));if(v){p=M.parameters(v.p);if(['static','dynamic'].includes(v.mode))mode=v.mode;if(Number.isFinite(v.phase))$('phase').value=Math.max(0,Math.min(100,v.phase));}}catch{}
keys.forEach(k=>$(k).value=p[k]);$('mode').value=mode;
function svg(tag,attrs){return '<'+tag+' '+Object.entries(attrs).map(([k,v])=>`${k}="${v}"`).join(' ')+'/>';}
function draw(){const phase=+$('phase').value/100,s=M.state(p,phase,mode),scale=450/(p.shin+p.thigh+p.torso+.12),X=x=>330+x*scale,Y=y=>540-y*scale;let scene='';
scene+=svg('path',{d:'M30 540H690',stroke:'#363e49','stroke-width':2});scene+=svg('path',{d:`M${X(-.09)} 535H${X(.20)}`,stroke:'#e0e7ee','stroke-width':8,'stroke-linecap':'round'});
scene+=svg('path',{d:`M${X(s.ankle.x)} ${Y(s.ankle.y)}L${X(s.knee.x)} ${Y(s.knee.y)}L${X(s.hip.x)} ${Y(s.hip.y)}L${X(s.shoulder.x)} ${Y(s.shoulder.y)}`,stroke:'#b4c0cc','stroke-width':18,'stroke-linejoin':'round',fill:'none'});
for(const [name,pt] of Object.entries({ankle:s.ankle,knee:s.knee,hip:s.hip}))scene+=svg('circle',{cx:X(pt.x),cy:Y(pt.y),r:9,stroke:colors[name],'stroke-width':4,fill:'#101216'});
scene+=svg('circle',{cx:X(s.shoulder.x),cy:Y(s.shoulder.y+.09),r:16,fill:'#a6b3c1'});
scene+=svg('path',{d:`M${X(s.shoulder.x)-48} ${Y(s.shoulder.y)}H${X(s.shoulder.x)+48}`,stroke:'#f6c915','stroke-width':6});
for(const dx of [-37,37])scene+=svg('rect',{x:X(s.shoulder.x)+dx-6,y:Y(s.shoulder.y)-19,width:12,height:38,rx:3,fill:'#f6c915'});
scene+=svg('path',{d:`M${X(s.com.x)} ${Y(s.com.y)}V540`,stroke:'#5ce5f5','stroke-width':1,'stroke-dasharray':'5 6'});scene+=svg('circle',{cx:X(s.com.x),cy:Y(s.com.y),r:7,fill:'#5ce5f5'});
if(s.cop!==null){const x=X(s.cop),dx=s.Fx/15,dy=Math.min(180,Math.max(-180,s.Fy/15));scene+=svg('path',{d:`M${x} 540l${dx} ${-dy}`,stroke:s.valid?'#47ff9e':'#ff8a3d','stroke-width':4});scene+=svg('circle',{cx:x,cy:540,r:6,fill:s.valid?'#47ff9e':'#ff8a3d'});scene+=svg('path',{d:`M${x+dx-5} ${540-dy+9}L${x+dx} ${540-dy}L${x+dx+5} ${540-dy+9}`,stroke:'#47ff9e',fill:'none','stroke-width':3});}
$('scene').innerHTML=scene;for(const k of ['hip','knee','ankle'])$(k+'Moment').textContent=(s.moments[k]>0?'+':'')+s.moments[k].toFixed(1)+' N·m';$('reaction').textContent=`Fx ${s.Fx.toFixed(0)} N · Fy ${s.Fy.toFixed(0)} N`;$('cop').textContent=s.cop===null?'—':(s.cop*100).toFixed(1)+' cm';$('angles').textContent=['hip','knee','ankle'].map(k=>T[k]+' '+s.angles[k].toFixed(0)+'°').join(' · ');$('phaseOut').textContent=Math.round(phase*100)+'%';$('feasibility').textContent=s.valid?T.valid:T.invalid;$('feasibility').className=s.valid?'':'invalid';keys.forEach(k=>$(k+'Out').textContent=p[k]+' '+$(k).dataset.unit);chart(phase);
}
function chart(phase){const max=Math.max(1,...trace.flatMap(s=>Object.values(s.moments).map(Math.abs)))*1.1;const yy=v=>135-v/max*105;let html=svg('path',{d:'M55 30V240M55 135H780',stroke:'#535c69',fill:'none'});for(const y of [-max,0,max])html+=`<text x="2" y="${yy(y)+4}" fill="#a0a0a8" font-size="12">${y.toFixed(0)}</text>`;for(const k of ['hip','knee','ankle']){html+=svg('path',{d:trace.map((s,i)=>(i?'L':'M')+(55+725*i/(trace.length-1)).toFixed(1)+' '+yy(s.moments[k]).toFixed(1)).join(' '),stroke:colors[k],'stroke-width':3,fill:'none'});}html+=svg('path',{d:`M${55+725*phase} 20V245`,stroke:'#f6c915','stroke-width':2,'stroke-dasharray':'4 5'});$('chart').innerHTML=html;}
function rebuild(){trace=M.cycle(p,mode);draw();}
function stop(){running=false;cancelAnimationFrame(frame);last=null;$('play').textContent=T.play;$('play').setAttribute('aria-pressed','false');}
function animate(now){if(!running)return;if(last!==null)$('phase').value=(+$('phase').value+(now-last)*.1/p.period)%100;last=now;draw();frame=requestAnimationFrame(animate);}
keys.forEach(k=>$(k).addEventListener('input',()=>{stop();p=M.parameters({...p,[k]:+$(k).value});rebuild();}));$('mode').addEventListener('change',()=>{stop();mode=$('mode').value;rebuild();});$('phase').addEventListener('input',()=>{stop();draw();});$('play').addEventListener('click',()=>{if(running)return stop();running=true;$('play').textContent=T.pause;$('play').setAttribute('aria-pressed','true');frame=requestAnimationFrame(animate);});$('reset').addEventListener('click',()=>{stop();p=M.parameters();mode='dynamic';keys.forEach(k=>$(k).value=p[k]);$('mode').value=mode;$('phase').value=50;rebuild();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',()=>{try{sessionStorage.setItem(storage,JSON.stringify({p,mode,phase:+$('phase').value}));}catch{}});rebuild();})();
